// What a saved experiment keeps of a run's result (runs stored by older versions also carried comparison counts).
const ragResOut=R=>({hit:R.hit,ok:R.ok,ref:R.ref,n:R.n,nOos:R.nOos,prec:R.prec,...(isObj(R.byType)?{byType:Object.fromEntries(Object.entries(R.byType).filter(([,v])=>isObj(v)).map(([k,v])=>[k,{n:v.n,ok:v.ok}]))}:{})});
