 // ─── 1 + 2: documents and fragments (local, instant) ───
 const drawDocs=()=>{const L=lab().rag,ids=ragDocIds(L),rv=L.revealed;$$('#ragDocs [data-doc-id]').forEach(c=>{c.checked=ids.includes(c.dataset.docId);c.disabled=rv;c.closest('.rag-doc').dataset.on=c.checked});
  const arch=ids.filter(DOC_ARCHIVED);$('#ragDocsN').innerHTML=T(`W bazie: ${ids.length} z ${DOCS.length} dokumentów.`,`In the base: ${ids.length} of ${DOCS.length} documents.`)+(arch.length?` <span class="edu-chip tone-red">${T('uwaga')}</span> ${T(`Wśród nich jest wersja archiwalna (${arch.join(', ')}), która już nie obowiązuje.`,`One of them is an archived version (${arch.join(', ')}) that is no longer in force.`)}`:'')};
