   +`<div class="row mt"><label for="ragChunkDoc" class="edu-small">${T('Pokażcie fragmenty dokumentu')}:</label><select id="ragChunkDoc" class="input" style="width:auto"><option value="">${T('wszystkie dokumenty')}</option>${ids.map(id=>`<option value="${id}" ${id===f?'selected':''}>${id}</option>`).join('')}</select><span class="edu-small">${T('Kliknijcie fragment, aby go przeczytać.')}</span></div>
   <div class="rag-frags mt" id="ragFrags">${list.map(c=>`<button type="button" class="rag-frag" data-frag="${c.i}" data-doc="${c.doc}"><span class="rag-sw" style="background:${ragDocCol(c.doc)}"></span><b>${c.doc} §${c.par}</b><span class="rf-w">${rcnt(c.words,'word')}</span><span class="rf-x">${esc(c.text.slice(0,110))}${c.text.length>110?'…':''}</span></button>`).join('')||`<p class="hint" style="margin:0">${T('Zaznaczcie co najmniej jeden dokument.')}</p>`}</div>`;
  $('#ragChunkDoc').onchange=e=>{X.ragChunkDoc=e.target.value;drawChunks()};
